                    item_code: item_code,
                    item_name: item.item_name || '',
                    qty: qty,
                    uom: item.uom || '',
                    rate: rate,
                    amount: amount
                });

                // Add to item summary
                if (!item_summary[item_code]) {
                    item_summary[item_code] = {
                        item_name: item.item_name || '',
                        total_qty: 0,
                        uom: item.uom || '',
                        avg_rate: 0,
                        total_amount: 0,
