                    }
                });
            }, __('Actions'));
        }
    },
    
    // Validate before submit
    before_submit: function(frm) {
        if (frm.doc.job_execution && frm.doc.job_execution.length > 0) {
            let missing_fields = [];
            
            frm.doc.job_execution.forEach(function(row, index) {
                if (!row.employee) {
                    missing_fields.push(`Row ${index + 1}: Employee is required`);
                }
                if (!row.date) {
                    missing_fields.push(`Row ${index + 1}: Date is required`);
                }
            });
            
            if (missing_fields.length > 0) {
                frappe.msgprint({
                    title: __('Missing Required Fields'),
                    message: missing_fields.join('<br>'),
                    indicator: 'red'
                });
                frappe.validated = false;
            }
        }
    }
});
